# -*- coding: utf-8 -*-
"""home_v2_module — LoadBoot header v2 (mega-menu) + six redesigned homepage sections (13 Sep 2026).

Additive and reversible: build_site.py imports these and switches on HEADER_V2 / HOME_V2.
Set either flag to False in build_site.py to fall back to the previous header / sections.
Source previews (approved by owner): previews/header-megamenu-v2.html, previews/home-sections-v2.html.
All CSS is prefixed lbh- (header) and hs- (sections); design tokens are scoped, not on :root.
Colors: brand kit only (Navy #10223B, Blue #0883F7, Orange #FC5305); green used for status only.
"""
import re as _re

LBH_CSS = '\n/* ===== LB-HEADER-V2 (13 Sep 2026) — additive; HEADER_V2=False in build_site.py rolls back ===== */\n.lbh-topbar,.lbh,.lbh-drawer{--ink:#10223B;--ink-2:#2E4160;--muted:#5D6E86;--muted-2:#8A99B0;--line:#E2E8F1;--line-2:#EEF2F8;--tint:#F4F7FB;--tint-2:#EAF1FA;--blue-soft:#EAF3FE;--blue-2:#4EA6F9;--glass:rgba(255,255,255,.86);--promo-a:#0B1830;--promo-b:#142A4A;--r:18px}\n.lbh .wrap{position:relative}\n.lbh{z-index:200}.lbh-drawer{z-index:300}\n.lbh-topbar .wrap{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:36px}\n.lbh-top{font-family:\'Manrope\',sans-serif}\n.lbh a::after{display:none}\n/* ---------- topbar (refined, slimmer) ---------- */\n.lbh-topbar{background:linear-gradient(90deg,#0B1830,#10223B 55%,#132C4E);color:#A9BBD4;font-size:.78rem;letter-spacing:.01em}\n.lbh-topbar .wrap{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:36px}\n.lbh-tb-tag{display:inline-flex;align-items:center;gap:8px;font-family:\'Manrope\',sans-serif;font-weight:700;letter-spacing:.08em;text-transform:uppercase;font-size:.68rem;color:#C9D6E8}\n.lbh-tb-tag i{width:6px;height:6px;border-radius:50%;background:var(--orange);box-shadow:0 0 0 3px rgba(252,83,5,.22)}\n.lbh-tb-right{display:flex;align-items:center;gap:18px;white-space:nowrap}\n.lbh-tb-call{color:#fff;font-weight:700;display:inline-flex;align-items:center;gap:7px}\n.lbh-tb-call svg{color:#4EA6F9}\n.lbh-tb-call:hover{color:#4EA6F9}\n.lbh-tb-cb{color:#FC8B57;font-weight:600}\n.lbh-tb-cb:hover{color:#fff}\n.lbh-tb-sep{width:1px;height:14px;background:rgba(255,255,255,.14)}\n\n/* ---------- header bar ---------- */\n.lbh{position:sticky;top:0;z-index:200;background:var(--glass);-webkit-backdrop-filter:saturate(1.4) blur(16px);backdrop-filter:saturate(1.4) blur(16px);border-bottom:1px solid transparent;transition:border-color .3s,box-shadow .3s}\n.lbh.scrolled,.lbh.is-open{border-bottom-color:var(--line);box-shadow:0 10px 40px -24px rgba(16,34,59,.45)}\n.lbh .wrap{position:relative}\n.lbh-bar{display:flex;align-items:center;justify-content:space-between;height:72px;gap:24px}\n.lbh-logo{display:flex;align-items:center;flex:none}\n.lbh-logo img{display:block;height:36px;width:auto}\n\n.lbh-nav{display:flex;align-items:stretch;align-self:stretch;gap:4px}\n.lbh-item{position:static;display:flex;align-items:center}\n.lbh-top{display:inline-flex;align-items:center;gap:6px;height:40px;padding:0 14px;border-radius:12px;font-family:\'Manrope\',sans-serif;font-weight:700;font-size:.93rem;color:var(--ink-2);background:transparent;border:0;cursor:pointer;transition:background .18s,color .18s;position:relative}\n.lbh-top:hover,.lbh-item.is-open>.lbh-top,.lbh-item:hover>.lbh-top,.lbh-top.active{color:var(--navy);background:var(--tint)}\n.lbh-top.active::after{content:"";position:absolute;left:14px;right:14px;bottom:-1px;height:2px;border-radius:2px;background:var(--blue)}\n.lbh-caret{width:12px;height:12px;opacity:.55;transition:transform .22s cubic-bezier(.2,.8,.2,1)}\n.lbh-item:hover .lbh-caret,.lbh-item.is-open .lbh-caret{transform:rotate(180deg);opacity:1;color:var(--blue)}\n\n.lbh-actions{display:flex;align-items:center;gap:10px;flex:none}\n.lbh-btn{display:inline-flex;align-items:center;gap:8px;height:42px;padding:0 18px;border-radius:12px;font-family:\'Manrope\',sans-serif;font-weight:700;font-size:.92rem;border:1px solid transparent;transition:.2s;white-space:nowrap}\n.lbh-btn svg{transition:transform .2s}\n.lbh-login{color:var(--navy);border-color:var(--line);background:#fff}\n.lbh-login:hover{border-color:var(--blue);color:var(--blue)}\n.lbh-go{background:var(--orange);color:#fff;box-shadow:0 10px 22px -10px rgba(252,83,5,.6)}\n.lbh-go:hover{background:#EA4B02;transform:translateY(-1px)}\n.lbh-go:hover svg{transform:translateX(3px)}\n.lbh-burger{display:none;width:44px;height:44px;border-radius:12px;border:1px solid var(--line);background:#fff;color:var(--navy);align-items:center;justify-content:center;cursor:pointer}\n.lbh-burger:hover{border-color:var(--blue);color:var(--blue)}\n\n/* ---------- mega panel ---------- */\n.lbh-panel{position:absolute;left:24px;right:24px;top:calc(100% - 6px);background:#fff;border:1px solid var(--line);border-radius:var(--r);box-shadow:0 40px 90px -30px rgba(16,34,59,.35),0 2px 6px rgba(16,34,59,.05);opacity:0;visibility:hidden;transform:translateY(8px);transition:opacity .2s,transform .22s cubic-bezier(.2,.8,.2,1),visibility 0s .2s;pointer-events:none;overflow:hidden;z-index:90}\n.lbh-panel::before{content:"";position:absolute;left:0;right:0;top:0;height:2px;background:linear-gradient(90deg,var(--blue) 0%,#4EA6F9 45%,var(--orange) 100%);opacity:.9}\n.lbh-item:hover>.lbh-panel,.lbh-item.is-open>.lbh-panel,.lbh-item:focus-within>.lbh-panel{opacity:1;visibility:visible;transform:translateY(0);pointer-events:auto;transition:opacity .2s,transform .22s cubic-bezier(.2,.8,.2,1),visibility 0s}\n.lbh-grid{display:grid;grid-template-columns:1.15fr 1.15fr 1fr 290px;gap:0}\n.lbh-grid>*{padding:24px 20px 22px}\n.lbh-grid>*+*{border-left:1px solid var(--line-2)}\n.lbh-col.compact{grid-template-columns:1.35fr 1fr .9fr 300px}\n.lbh-eyebrow{font-family:\'Manrope\',sans-serif;font-weight:700;font-size:.66rem;letter-spacing:.12em;text-transform:uppercase;color:var(--muted-2);margin:0 0 12px 10px}\n.lbh-list{display:flex;flex-direction:column;gap:2px;margin:0;padding:0;list-style:none}\n\n.lbh-row{display:flex;align-items:flex-start;gap:12px;padding:10px 10px;border-radius:12px;transition:background .15s}\n.lbh-row:hover{background:var(--tint)}\n.lbh-ico{flex:none;width:38px;height:38px;border-radius:11px;background:var(--tint-2);color:var(--navy);display:grid;place-items:center;transition:background .15s,color .15s,transform .15s}\n.lbh-ico svg{width:19px;height:19px}\n.lbh-row:hover .lbh-ico{background:var(--blue);color:#fff;transform:translateY(-1px)}\n.lbh-row b{display:block;font-family:\'Manrope\',sans-serif;font-weight:700;font-size:.93rem;color:var(--navy);line-height:1.25}\n.lbh-row span{display:block;font-size:.82rem;color:var(--muted);line-height:1.4;margin-top:2px}\n.lbh-row.active b{color:var(--blue)}\n\n.lbh-plain{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:9px 10px;white-space:nowrap;border-radius:10px;font-family:\'Manrope\',sans-serif;font-weight:700;font-size:.9rem;color:var(--ink-2);transition:background .15s,color .15s}\n.lbh-plain:hover{background:var(--tint);color:var(--blue)}\n.lbh-plain svg{width:14px;height:14px;opacity:0;transform:translateX(-4px);transition:.15s;color:var(--blue)}\n.lbh-plain:hover svg{opacity:1;transform:none}\n.lbh-plain.more{color:var(--blue);margin-top:6px}\n.lbh-plain.more svg{opacity:1;transform:none}\n.lbh-tag{font-family:\'Manrope\',sans-serif;font-weight:800;font-size:.6rem;letter-spacing:.06em;text-transform:uppercase;padding:2px 7px;border-radius:99px;background:rgba(252,83,5,.1);color:#D94700}\n\n/* promo card (navy, brand route-line motif) */\n.lbh-promo{position:relative;background:linear-gradient(160deg,var(--promo-a),var(--promo-b));color:#fff;padding:26px!important;display:flex;flex-direction:column;gap:14px;border-left:0!important;overflow:hidden;isolation:isolate}\n.lbh-promo::before{content:"";position:absolute;inset:0;background:radial-gradient(420px 220px at 110% -20%,rgba(8,131,247,.32),transparent 60%),radial-gradient(300px 200px at -10% 120%,rgba(252,83,5,.18),transparent 60%);z-index:-1}\n.lbh-promo .route{color:#4EA6F9;height:28px}\n.lbh-promo h4{margin:0;font-family:\'Manrope\',sans-serif;font-weight:800;font-size:1.18rem;line-height:1.2;letter-spacing:-.01em;text-wrap:balance}\n.lbh-promo h4 em{font-style:normal;color:#4EA6F9}\n.lbh-promo p{margin:0;font-size:.86rem;color:#B6C6DD;line-height:1.5;max-width:26ch}\n.lbh-promo-btn{margin-top:auto;display:inline-flex;align-items:center;justify-content:center;gap:8px;height:42px;padding:0 16px;border-radius:12px;background:var(--blue);color:#fff;font-family:\'Manrope\',sans-serif;font-weight:700;font-size:.9rem;transition:.2s}\n.lbh-promo-btn:hover{background:#4EA6F9;color:#06131F}\n.lbh-promo-btn.ghost{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18)}\n.lbh-promo-btn.ghost:hover{background:rgba(255,255,255,.16);color:#fff}\n.lbh-promo-list{list-style:none;margin:0;padding:0;display:grid;gap:8px;font-size:.84rem;color:#DCE6F4}.lbh-promo-list li{display:flex;align-items:center;gap:9px}.lbh-promo-list li::before{content:"";width:7px;height:7px;border-radius:50%;flex:none;background:var(--blue-2);box-shadow:0 0 0 3px rgba(78,166,249,.25)}\n.lbh-promo-foot{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:.78rem;color:#8FA5C4}\n.lbh-promo-foot b{color:#fff;font-weight:600}\n.lbh-portals{display:grid;gap:8px}\n.lbh-portal{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:12px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);font-family:\'Manrope\',sans-serif;font-weight:700;font-size:.88rem;transition:.15s}\n.lbh-portal:hover{background:rgba(255,255,255,.12);border-color:rgba(78,166,249,.5)}\n.lbh-portal i{width:8px;height:8px;border-radius:50%;flex:none}\n.lbh-portal small{margin-left:auto;font-family:\'Inter\';font-weight:500;font-size:.74rem;color:#8FA5C4}\n\n/* bottom strip of panel */\n.lbh-strip{grid-column:1/-1;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px 26px!important;border-top:1px solid var(--line-2);border-left:0!important;background:var(--tint);font-size:.82rem;color:var(--muted)}\n.lbh-strip a{color:var(--navy);font-weight:600;display:inline-flex;align-items:center;gap:6px}\n.lbh-strip a:hover{color:var(--blue)}\n.lbh-strip .dot{width:7px;height:7px;border-radius:50%;background:#12A150;box-shadow:0 0 0 3px rgba(18,161,80,.18)}\n\n/* ---------- mobile drawer ---------- */\n.lbh-drawer{display:none}\n@media(max-width:1120px){\n  .lbh-nav,.lbh-btn.lbh-login{display:none}\n  .lbh-burger{display:inline-flex}\n  .lbh-bar{height:64px}\n  .lbh-logo img{height:32px}\n  .lbh-go{height:40px;padding:0 14px;font-size:.88rem}\n  .lbh-drawer{display:block;position:fixed;inset:0;z-index:300;background:rgba(16,34,59,.35);-webkit-backdrop-filter:blur(4px);backdrop-filter:blur(4px);opacity:0;visibility:hidden;transition:.25s}\n  .lbh-drawer.open{opacity:1;visibility:visible}\n  .lbh-sheet{position:absolute;top:0;right:0;bottom:0;width:min(420px,100%);background:#fff;display:flex;flex-direction:column;transform:translateX(24px);transition:transform .3s cubic-bezier(.2,.8,.2,1);box-shadow:-30px 0 80px -30px rgba(16,34,59,.5)}\n  .lbh-drawer.open .lbh-sheet{transform:none}\n  .lbh-sheet-head{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid var(--line)}\n  .lbh-sheet-head img{height:30px}\n  .lbh-x{width:40px;height:40px;border-radius:10px;border:1px solid var(--line);background:#fff;display:grid;place-items:center;cursor:pointer;color:var(--navy)}\n  .lbh-sheet-body{flex:1;overflow:auto;padding:8px 10px 16px}\n  .lbh-acc{border-bottom:1px solid var(--line-2)}\n  .lbh-acc>summary{list-style:none;display:flex;align-items:center;justify-content:space-between;padding:14px 10px;font-family:\'Manrope\',sans-serif;font-weight:800;font-size:1.02rem;color:var(--navy);cursor:pointer;border-radius:10px}\n  .lbh-acc>summary::-webkit-details-marker{display:none}\n  .lbh-acc>summary svg{width:16px;height:16px;transition:transform .2s;color:var(--muted-2)}\n  .lbh-acc[open]>summary svg{transform:rotate(180deg);color:var(--blue)}\n  .lbh-acc .lbh-eyebrow{margin:10px 0 6px 10px}\n  .lbh-acc .lbh-row{padding:9px 10px}\n  .lbh-acc .lbh-ico{width:34px;height:34px}\n  .lbh-acc-body{padding-bottom:10px}\n  .lbh-mlink{display:flex;align-items:center;justify-content:space-between;padding:14px 10px;font-family:\'Manrope\',sans-serif;font-weight:800;font-size:1.02rem;color:var(--navy);border-bottom:1px solid var(--line-2)}\n  .lbh-sheet-foot{padding:14px 18px 18px;border-top:1px solid var(--line);display:grid;gap:10px;background:var(--tint)}\n  .lbh-sheet-foot .lbh-btn{height:46px;justify-content:center;display:inline-flex}\n  .lbh-sheet-call{display:flex;align-items:center;justify-content:center;gap:8px;font-weight:600;color:var(--navy);font-size:.92rem}\n  .lbh-sheet-call svg{color:var(--blue)}\n}\n@media(max-width:700px){.lbh-topbar .lbh-tb-tag{display:none}.lbh-topbar .wrap{justify-content:center}}\n@media(max-width:420px){.lbh-tb-cb{display:none}.lbh-tb-sep{display:none}}\n@media(prefers-reduced-motion:reduce){.lbh *,.lbh-drawer *,.lbh-topbar *{transition:none!important}}\n\n'

HS_CSS = '\n/* ===== LB-HOME-V2 (13 Sep 2026) — additive; HOME_V2=False in build_site.py rolls back ===== */\n.hs-scope{--ink:#10223B;--ink-2:#2E4160;--muted:#5D6E86;--muted-2:#8A99B0;--line:#E2E8F1;--line-2:#EEF2F8;--tint:#F4F7FB;--tint-2:#EAF1FA;--soft:#F6F8FB;--ok:#12A150;--ok-bg:#E7F9EE;--bad:#C62828;--bad-bg:#FDECEC;--mid:#B45309;--mid-bg:#FFF4E6;--dk:#0B1830;--dk-2:#10223B;--dk-3:#142A4A;--blue-2:#4EA6F9;--orange-2:#FC8B57}\n.hs-scope h2,.hs-scope h3{text-wrap:balance}\n.hs-scope .sec-head{margin-bottom:0}\n.hs-cta{display:flex;flex-wrap:wrap;gap:12px;justify-content:center;margin-top:32px}\n.hs-ico{display:grid;place-items:center;flex:none}.hs-ico svg{width:20px;height:20px}\n.hs-fn{font-size:.82rem;color:var(--muted);max-width:72ch}\n.hs-btn-ghost{background:rgba(255,255,255,.07);color:#fff;border-color:rgba(255,255,255,.22)}.hs-btn-ghost:hover{background:rgba(255,255,255,.14);border-color:rgba(255,255,255,.4);color:#fff}\n.hs-dark{background:var(--dk);color:#fff}.hs-dark .eyebrow{color:var(--blue-2)}.hs-dark h2{color:#fff}.hs-dark .lead{color:#B6C6DD}\n.hs-scope .lead{color:var(--muted)}.hs-scope .center .lead{margin-left:auto;margin-right:auto}\n@media(max-width:720px){.hs-cta .btn{width:100%}}\n/* S1 — THE LOADBOOT STANDARD (replaces the green 4-tile band)\n   ================================================================= */\n.hs-std{background:linear-gradient(160deg,var(--dk) 0%,var(--dk-2) 55%,var(--dk-3) 100%);color:#fff;position:relative;overflow:hidden;border-radius:24px;padding:40px}\n.hs-std::before{content:"";position:absolute;inset:0;background:radial-gradient(700px 320px at 100% -10%,rgba(8,131,247,.28),transparent 60%),radial-gradient(500px 300px at -5% 110%,rgba(252,83,5,.16),transparent 60%);pointer-events:none}\n.hs-std>*{position:relative}\n.hs-std-head{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;flex-wrap:wrap}\n.hs-std-head .eyebrow{color:var(--blue-2)}\n.hs-std-head h2{color:#fff;max-width:22ch}\n.hs-std-head p{color:#B6C6DD;margin:0;max-width:40ch;font-size:.95rem}\n.hs-std-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:30px}\n.hs-rule{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:18px;padding:22px 20px;display:flex;flex-direction:column;gap:12px;transition:.2s}\n.hs-rule:hover{background:rgba(255,255,255,.08);border-color:rgba(78,166,249,.45);transform:translateY(-2px)}\n.hs-rule .hs-ico{width:42px;height:42px;border-radius:12px;background:rgba(8,131,247,.18);color:var(--blue-2)}\n.hs-rule h3{font-size:1.12rem;color:#fff}\n.hs-rule p{margin:0;color:#B6C6DD;font-size:.9rem;line-height:1.5}\n.hs-rule .hs-enf{margin-top:auto;display:flex;align-items:flex-start;gap:8px;padding-top:12px;border-top:1px solid rgba(255,255,255,.1);font-size:.8rem;color:#DCE6F4}\n.hs-rule .hs-enf b{color:var(--orange-2);font-family:\'Manrope\';font-weight:700;font-size:.66rem;letter-spacing:.1em;text-transform:uppercase;display:block;margin-bottom:2px}\n.hs-rule .hs-enf svg{width:16px;height:16px;flex:none;color:var(--ok);margin-top:1px}\n@media(max-width:1000px){.hs-std-grid{grid-template-columns:1fr 1fr}}\n@media(max-width:600px){.hs-std{padding:28px 20px;border-radius:20px}.hs-std-grid{grid-template-columns:1fr}}\n\n/* =================================================================\n   S2 — WHY CARRIERS CHOOSE US (comparison matrix)\n   ================================================================= */\n.hs-cmp-wrap{margin-top:34px;background:#fff;border:1px solid var(--line);border-radius:20px;overflow:hidden;box-shadow:0 30px 60px -40px rgba(16,34,59,.35)}\n.hs-cmp{width:100%;border-collapse:separate;border-spacing:0;font-size:.92rem}\n.hs-cmp th,.hs-cmp td{padding:16px 18px;text-align:left;vertical-align:middle;border-bottom:1px solid var(--line-2)}\n.hs-cmp tbody tr:last-child td{border-bottom:0}\n.hs-cmp thead th{font-family:\'Manrope\';font-weight:700;font-size:.8rem;letter-spacing:.02em;color:var(--muted);background:var(--tint);border-bottom:1px solid var(--line)}\n.hs-cmp thead th:first-child{color:var(--navy);font-size:.86rem}\n.hs-cmp th.hs-us,.hs-cmp td.hs-us{background:linear-gradient(180deg,#F1F7FE,#fff);border-left:1px solid var(--line);border-right:1px solid var(--line)}\n.hs-cmp thead th.hs-us{background:var(--navy);color:#fff;position:relative}\n.hs-cmp thead th.hs-us::before{content:"";position:absolute;left:0;right:0;top:0;height:3px;background:linear-gradient(90deg,var(--blue),var(--orange))}\n.hs-cmp thead th.hs-us .hs-lg{display:flex;align-items:center;gap:8px;font-size:.95rem}\n.hs-cmp thead th.hs-us .hs-lg i{width:22px;height:22px;border-radius:6px;background:var(--orange);display:grid;place-items:center;font-style:normal}\n.hs-cmp thead th.hs-us .hs-lg i svg{width:13px;height:13px}\n.hs-cmp td:first-child{font-weight:600;color:var(--navy)}\n.hs-cmp td:first-child small{display:block;font-weight:400;color:var(--muted);font-size:.8rem;margin-top:2px}\n.hs-cell{display:inline-flex;align-items:center;gap:8px;font-weight:500;color:var(--ink-2)}\n.hs-cell i{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;flex:none;font-style:normal}\n.hs-cell i svg{width:12px;height:12px}\n.hs-cell.hs-bad i{background:var(--bad-bg);color:var(--bad)}\n.hs-cell.hs-mid i{background:var(--mid-bg);color:var(--mid)}\n.hs-cell.hs-good i{background:var(--ok-bg);color:var(--ok)}\n.hs-cell.hs-good{color:var(--navy);font-weight:600}\n.hs-cmp td.hs-us .hs-cell{font-weight:700;color:var(--navy)}\n.hs-cmp-foot{display:flex;flex-wrap:wrap;justify-content:space-between;gap:12px 24px;padding:16px 20px;background:var(--tint);border-top:1px solid var(--line);font-size:.82rem;color:var(--muted)}\n.hs-cmp-foot .hs-legend{display:flex;gap:16px;flex-wrap:wrap}\n.hs-cmp-foot .hs-legend span{display:inline-flex;align-items:center;gap:6px}\n.hs-cmp-foot .hs-legend i{width:10px;height:10px;border-radius:50%}\n@media(max-width:760px){\n  .hs-cmp-wrap{border-radius:16px}\n  .hs-cmp th,.hs-cmp td{padding:12px 8px}\n  .hs-cmp{font-size:.78rem}\n  .hs-cmp td:first-child{font-size:.8rem;padding-left:12px;width:38%}\n  .hs-cmp td:first-child small{display:none}\n  .hs-cmp thead th{font-size:.66rem;padding:12px 8px;line-height:1.25}\n  .hs-cmp thead th:first-child{padding-left:12px}\n  .hs-cmp thead th.hs-us .hs-lg{font-size:.8rem;gap:5px}\n  .hs-cell{flex-direction:column;align-items:flex-start;gap:4px;font-size:.72rem;line-height:1.25}\n  .hs-cell i{width:20px;height:20px}\n  .hs-cmp-foot{padding:12px 14px}\n}\n\n/* =================================================================\n   S3 — HOW FREIGHT MOVES (bridge diagram)\n   ================================================================= */\n.hs-flow{display:grid;grid-template-columns:1fr 64px 1.25fr 64px 1fr;align-items:stretch;gap:0;margin-top:40px;max-width:1080px;margin-inline:auto}\n.hs-node{background:#fff;border:1px solid var(--line);border-radius:20px;padding:26px 24px;display:flex;flex-direction:column;gap:12px;position:relative}\n.hs-node .hs-who{display:flex;align-items:center;gap:12px}\n.hs-node .hs-who .hs-ico{width:44px;height:44px;border-radius:13px;background:var(--tint-2);color:var(--navy)}\n.hs-node h3{font-size:1.15rem}\n.hs-node .hs-who small{display:block;color:var(--muted);font-size:.78rem;font-weight:500}\n.hs-node ul{list-style:none;margin:4px 0 0;padding:0;display:grid;gap:9px}\n.hs-node li{display:flex;gap:9px;align-items:flex-start;font-size:.9rem;color:var(--ink-2);line-height:1.45}\n.hs-node li svg{width:16px;height:16px;flex:none;color:var(--blue);margin-top:2px}\n.hs-node.hs-core{background:linear-gradient(160deg,var(--dk),var(--dk-3));color:#fff;border:0;box-shadow:0 40px 80px -40px rgba(8,131,247,.6);overflow:hidden}\n.hs-node.hs-core::before{content:"";position:absolute;inset:0;background:radial-gradient(400px 220px at 100% 0%,rgba(8,131,247,.35),transparent 60%);pointer-events:none}\n.hs-node.hs-core>*{position:relative}\n.hs-node.hs-core .hs-who .hs-ico{background:var(--blue);color:#fff;box-shadow:0 0 0 6px rgba(8,131,247,.22)}\n.hs-node.hs-core h3{color:#fff}\n.hs-node.hs-core .hs-who small{color:#8FA5C4}\n.hs-core-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:6px}\n.hs-core-grid div{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:12px;padding:10px 12px}\n.hs-core-grid b{display:block;font-family:\'Manrope\';font-size:.86rem;color:#fff}\n.hs-core-grid span{display:block;font-size:.76rem;color:#B6C6DD;line-height:1.35;margin-top:2px}\n.hs-link{display:flex;align-items:center;justify-content:center;position:relative}\n.hs-link::before{content:"";position:absolute;left:0;right:0;top:50%;height:2px;background-image:linear-gradient(90deg,var(--blue) 50%,transparent 50%);background-size:12px 2px;animation:dash 1.2s linear infinite}\n.hs-link i{position:relative;width:30px;height:30px;border-radius:50%;background:#fff;border:2px solid var(--blue);color:var(--blue);display:grid;place-items:center}\n.hs-link i svg{width:14px;height:14px}\n@keyframes dash{to{background-position:12px 0}}\n.hs-proof{display:flex;flex-wrap:wrap;justify-content:center;gap:10px;margin-top:28px}\n.hs-proof span{display:inline-flex;align-items:center;gap:8px;background:#fff;border:1px solid var(--line);border-radius:99px;padding:8px 14px;font-size:.84rem;font-weight:600;color:var(--navy)}\n.hs-proof span i{width:8px;height:8px;border-radius:50%;background:var(--ok);box-shadow:0 0 0 3px rgba(18,161,80,.18)}\n@media(max-width:900px){\n  .hs-flow{grid-template-columns:1fr;max-width:520px}\n  .hs-link{height:56px}\n  .hs-link::before{left:50%;right:auto;top:0;bottom:0;width:2px;height:auto;background-image:linear-gradient(180deg,var(--blue) 50%,transparent 50%);background-size:2px 12px;animation:dashv 1.2s linear infinite}\n  .hs-link i svg{transform:rotate(90deg)}\n  @keyframes dashv{to{background-position:0 12px}}\n}\n\n/* =================================================================\n   S4 — YOUR WEEK WITH LOADBOOT (process rail)\n   ================================================================= */\n.hs-rail{position:relative;display:grid;grid-template-columns:repeat(5,1fr);gap:16px;margin-top:48px}\n.hs-rail::before{content:"";position:absolute;left:8%;right:8%;top:22px;height:2px;background:linear-gradient(90deg,var(--blue),var(--blue-2) 60%,var(--orange));opacity:.35;z-index:0}\n.hs-step{position:relative;display:flex;flex-direction:column;gap:12px}\n.hs-step .hs-num{width:44px;height:44px;border-radius:50%;background:#fff;border:2px solid var(--blue);color:var(--blue);display:grid;place-items:center;font-family:\'Manrope\';font-weight:800;font-size:1rem;box-shadow:0 0 0 6px #fff;position:relative;z-index:1}\n.hs-step:last-child .hs-num{border-color:var(--orange);color:var(--orange)}\n.hs-step .hs-card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:20px 18px;display:flex;flex-direction:column;gap:10px;flex:1;transition:.2s}\n.hs-step .hs-card:hover{border-color:rgba(8,131,247,.45);box-shadow:0 24px 50px -34px rgba(16,34,59,.5);transform:translateY(-2px)}\n.hs-step .hs-ico{width:38px;height:38px;border-radius:11px;background:var(--tint-2);color:var(--navy)}\n.hs-step h3{font-size:1.02rem}\n.hs-step p{margin:0;color:var(--muted);font-size:.88rem;line-height:1.5}\n.hs-step .hs-when{font-family:\'Manrope\';font-weight:700;font-size:.66rem;letter-spacing:.12em;text-transform:uppercase;color:var(--blue)}\n.hs-mock{margin-top:auto;background:var(--tint);border:1px solid var(--line-2);border-radius:12px;padding:10px 12px;font-size:.76rem;color:var(--ink-2);display:flex;flex-wrap:wrap;gap:6px;align-items:center}\n.hs-mock .hs-pill{display:inline-flex;align-items:center;gap:5px;padding:4px 9px;border-radius:99px;background:#fff;border:1px solid var(--line);font-weight:600;color:var(--navy);font-size:.72rem}\n.hs-mock .hs-pill.hs-ok{border-color:rgba(18,161,80,.35);color:var(--ok);background:var(--ok-bg)}\n.hs-mock .hs-pill.hs-go{background:var(--blue);color:#fff;border-color:var(--blue)}\n.hs-mock .hs-pill.hs-no{color:var(--muted)}\n.hs-mock svg{width:11px;height:11px}\n.hs-mock .hs-arw{color:var(--muted-2)}\n@media(max-width:1000px){\n  .hs-rail{grid-template-columns:1fr;gap:0;max-width:560px;margin-inline:auto;padding-left:64px}\n  .hs-rail::before{left:21px;right:auto;top:8px;bottom:8px;width:2px;height:auto;background:linear-gradient(180deg,var(--blue),var(--blue-2) 60%,var(--orange))}\n  .hs-step{padding-bottom:18px}\n  .hs-step .hs-num{position:absolute;left:-64px;top:0}\n  .hs-step .hs-card{margin-top:0}\n}\n\n/* =================================================================\n   S5 — FOR BROKERS (dark panel + stepper)\n   ================================================================= */\n.hs-dark{background:var(--dk);color:#fff}\n.hs-dark .eyebrow{color:var(--blue-2)}\n.hs-dark .hs-h-unused{color:#fff}\n.hs-dark .lead{color:#B6C6DD}\n.hs-brk{display:grid;grid-template-columns:1.6fr 1fr;gap:20px;margin-top:40px;align-items:start}\n.hs-stepper{display:grid;gap:10px}\n.hs-bstep{display:grid;grid-template-columns:44px 1fr auto;gap:16px;align-items:center;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:16px;padding:16px 18px;transition:.2s}\n.hs-bstep:hover{background:rgba(255,255,255,.08);border-color:rgba(78,166,249,.4)}\n.hs-bstep .hs-n{width:44px;height:44px;border-radius:12px;background:rgba(8,131,247,.18);color:var(--blue-2);display:grid;place-items:center;font-family:\'Manrope\';font-weight:800}\n.hs-bstep h3{font-size:1.02rem;color:#fff}\n.hs-bstep p{margin:3px 0 0;color:#B6C6DD;font-size:.88rem;line-height:1.45}\n.hs-bstep .hs-t{font-family:\'Manrope\';font-weight:700;font-size:.72rem;letter-spacing:.06em;text-transform:uppercase;color:#8FA5C4;white-space:nowrap;text-align:right}\n.hs-bstep .hs-t b{display:block;color:#fff;font-size:.95rem;letter-spacing:0;text-transform:none}\n.hs-need{background:linear-gradient(160deg,var(--dk-2),var(--dk-3));border:1px solid rgba(255,255,255,.1);border-radius:20px;padding:26px;display:flex;flex-direction:column;gap:16px;position:sticky;top:24px}\n.hs-need .eyebrow{margin:0;color:var(--orange-2)}\n.hs-need h3{font-size:1.4rem;color:#fff}\n.hs-need h3 em{font-style:normal;color:var(--blue-2)}\n.hs-need p{margin:0;color:#B6C6DD;font-size:.9rem}\n.hs-need ul{list-style:none;margin:0;padding:0;display:grid;gap:9px}\n.hs-need li{display:flex;gap:10px;align-items:flex-start;font-size:.88rem;color:#DCE6F4}\n.hs-need li svg{width:16px;height:16px;flex:none;margin-top:2px;color:var(--ok)}\n.hs-need li.hs-later svg{color:#8FA5C4}\n.hs-need li.hs-later{color:#8FA5C4}\n.hs-need .hs-btns{display:grid;gap:8px;margin-top:4px}\n.hs-need .hs-btns .btn{width:100%}\n.hs-need .hs-ship{border-top:1px solid rgba(255,255,255,.1);padding-top:14px;font-size:.84rem;color:#B6C6DD}\n.hs-need .hs-ship a{color:var(--blue-2);font-weight:600}\n@media(max-width:900px){.hs-brk{grid-template-columns:1fr}.hs-need{position:static}}\n@media(max-width:560px){.hs-bstep{grid-template-columns:38px 1fr}.hs-bstep .hs-n{width:38px;height:38px}.hs-bstep .hs-t{grid-column:2;text-align:left;margin-top:-2px}.hs-bstep .hs-t b{display:inline;margin-left:6px}}\n\n/* =================================================================\n   S6 — AGENT PROGRAM\n   ================================================================= */\n.hs-agent{background:linear-gradient(135deg,var(--dk) 0%,#12304F 55%,#3B1A0E 100%);color:#fff;position:relative;overflow:hidden}\n.hs-agent::before{content:"";position:absolute;inset:0;background:radial-gradient(800px 400px at 90% 100%,rgba(252,83,5,.22),transparent 60%),radial-gradient(600px 300px at 0% 0%,rgba(8,131,247,.25),transparent 60%);pointer-events:none}\n.hs-agent .wrap{position:relative}\n.hs-agent .eyebrow{color:var(--orange-2)}\n.hs-agent .hs-h-unused{color:#fff}\n.hs-agent h2 em{font-style:normal;color:var(--blue-2)}\n.hs-agent .lead{color:#C9D6E8}\n.hs-agent .lead b{color:#fff}\n.hs-ag{display:grid;grid-template-columns:1.05fr 1fr;gap:36px;align-items:center}\n.hs-ag-left .hs-cta{justify-content:flex-start;margin-top:26px}\n.hs-ag-facts{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-top:26px}\n.hs-ag-facts div{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);border-radius:14px;padding:14px}\n.hs-ag-facts b{display:block;font-family:\'Manrope\';font-size:1.25rem;color:#fff;letter-spacing:-.02em}\n.hs-ag-facts span{display:block;font-size:.76rem;color:#B6C6DD;margin-top:2px;line-height:1.35}\n.hs-ladder{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.12);border-radius:22px;padding:24px;backdrop-filter:blur(8px);display:flex;flex-direction:column;gap:18px}\n.hs-ladder .hs-hd{display:flex;justify-content:space-between;align-items:baseline;gap:12px}\n.hs-ladder .hs-hd h3{font-size:1.02rem;color:#fff}\n.hs-ladder .hs-hd span{font-size:.74rem;color:#8FA5C4}\n.hs-lv{display:grid;grid-template-columns:70px 1fr 64px;gap:12px;align-items:center;font-size:.86rem}\n.hs-lv .hs-k{font-family:\'Manrope\';font-weight:700;color:#C9D6E8;font-size:.78rem}\n.hs-lv .hs-k small{display:block;font-family:\'Inter\';font-weight:400;color:#8FA5C4;font-size:.68rem}\n.hs-lv .hs-bar{height:12px;border-radius:99px;background:rgba(255,255,255,.08);overflow:hidden}\n.hs-lv .hs-bar i{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,var(--blue),var(--blue-2));width:var(--w);animation:grow 1s cubic-bezier(.2,.8,.2,1) both}\n.hs-lv.hs-l1 .hs-bar i{background:linear-gradient(90deg,var(--orange),var(--orange-2))}\n.hs-lv .hs-v{font-family:\'Manrope\';font-weight:800;color:#fff;text-align:right;font-variant-numeric:tabular-nums}\n@keyframes grow{from{width:0}}\n.hs-calc{border-top:1px solid rgba(255,255,255,.12);padding-top:16px;display:grid;gap:10px}\n.hs-calc label{display:flex;justify-content:space-between;font-size:.82rem;color:#C9D6E8;font-weight:500}\n.hs-calc label output{font-family:\'Manrope\';font-weight:800;color:#fff}\n.hs-calc input[type=range]{width:100%;accent-color:var(--orange);height:6px}\n.hs-calc .hs-res{display:flex;justify-content:space-between;align-items:center;gap:12px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);border-radius:14px;padding:12px 14px}\n.hs-calc .hs-res span{font-size:.78rem;color:#B6C6DD;line-height:1.35}\n.hs-calc .hs-res b{font-family:\'Manrope\';font-size:1.5rem;color:#fff;font-variant-numeric:tabular-nums;white-space:nowrap}\n.hs-calc .hs-res b small{font-size:.8rem;color:#8FA5C4;font-weight:600}\n.hs-agent .hs-fn{color:#8FA5C4;margin:26px auto 0;text-align:center}\n@media(max-width:900px){.hs-ag{grid-template-columns:1fr}.hs-ag-facts{grid-template-columns:1fr 1fr 1fr}}\n@media(max-width:560px){.hs-ag-facts{grid-template-columns:1fr}.hs-ag-facts div{display:flex;align-items:baseline;gap:12px}.hs-ag-facts b{min-width:110px}.hs-ag-facts span{margin:0}.hs-ladder{padding:18px}.hs-lv{grid-template-columns:58px 1fr 52px;gap:8px}}\n'

